#!/usr/bin/env python3
"""Impacted-tests runner (generated by secant). Runs only the existing tests that exercise the functions you
changed (from this repo's coverage data, recorded at an earlier commit), plus every test file you added or
edited, and reports failures. A fast alternative to running the whole suite while you iterate.

    python .secant/impacted.py          run them
    python .secant/impacted.py --list   only list them
"""

import os
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import verify as V  # noqa: E402  (shares diff parsing, coverage lookup and the pytest runner)

BUDGET_S = int(os.environ.get("SECANT_IMPACTED_BUDGET", "300"))
MAX_IDS = 400  # beyond this, run whole files (pytest's own collection is faster than a huge id list)


def main():
    c = V.cfg()
    root = V.root_commit()
    src = V.changed(root, c["src_prefixes"])
    own = V.changed(root, c["test_prefixes"])
    touched = V.touched_functions(root, src) if src else set()
    tests = V.impacted_tests(touched, [])
    files = list(dict.fromkeys(own + [t.split("::")[0] for t in tests]))
    targets = own + [t for t in tests if t.split("::")[0] not in own] if len(tests) <= MAX_IDS else files
    if not targets:
        print("Nothing to run: no source or test file has changed yet." if not src else
              f"No recorded test exercises the {len(touched)} function(s) you changed: "
              + ", ".join(sorted(touched)[:8]) + ". Run the test file for that area directly.")
        return 0
    print(f"{len(src)} changed source file(s), {len(touched)} changed function(s) -> {len(tests)} covering test(s) "
          f"in {len(files)} file(s)" + (f", plus {len(own)} test file(s) you changed" if own else "") + ".")
    if "--list" in sys.argv:
        print("\n".join(targets[:200]))
        return 0
    res, timed_out = V.run_pytest(targets, V.REPO, V.REPO, BUDGET_S)
    failing = {t: m for t, (s, m) in res.items() if s == "fail"}
    print(f"Ran {len(res)} test(s): {len(res) - len(failing)} passed, {len(failing)} failed"
          + (f" (stopped at the {BUDGET_S}s budget)" if timed_out else "") + ".")
    for t, m in list(failing.items())[:25]:
        print(f"  FAIL {t}: {m.strip()[:300]}")
    return 1 if failing else 0


if __name__ == "__main__":
    sys.exit(main())
